/* Hide all symbols except a few required ones.
 *
 * Otherwise LLVM symbols conflict with Mesa llvm pipe, boost symbols conflict
 * with Luxrender, etc. */
{
global:
  /* Essential symbols for the program to start and exit.
   * Use wildcard to avoid linker error on Android where these symbols do not exist. */
  _fini*;
  _init*;
  /* Needed for Python modules to work. */
  Py*;
  _Py*;
  /* Android's NativeActivity resolves this by name with dlsym, so hiding it
   * leaves the app unable to start. Supplied by the NDK glue and kept by the
   * -u link option in source/creator/CMakeLists.txt. Wildcard so the other
   * platforms, where it does not exist, still link. */
  ANativeActivity_onCreate*;
  /* Blender's own JNI entry points, for the same reason: the JVM resolves them
   * with dlsym, so hiding them turns every call from Java into an
   * UnsatisfiedLinkError at runtime rather than a link error at build time. */
  Java_org_blender_*;
  /* Needed for sanitizers. Based on:
   * llvm/compiler-rt/lib/sanitizer_common/scripts/gen_dynamic_list.py. */
  __asan*;
  __lsan*;
  __tsan*;
  __ubsan*;
  __sanitizer*;
  /* Memory allocation (new, delete, malloc). */
  __Znw*;
  __Zna*;
  __Zdl*;
  __Zda*;
  aligned_alloc*;
  calloc*;
  free*;
  mallinfo*;
  malloc*;
  mallopt*;
  memalign*;
  memcpy*;
  posix_memalign*;
  pthread_*;
  pvalloc*;
  realloc*;
  realpath*;
  sched_*;
  valloc*;
  /* Needed on FreeBSD. Uses wildcard to avoid linker error when symbols are not found. */
  __progname*;
  environ*;
local:
  *;
};
